// On Linux, set via: export MY_FLAG=""
// .NET 9 breaking change: on Linux, empty env vars now return null
// instead of "". Use a platform check to distinguish "not set" from "empty".
var val = Environment.GetEnvironmentVariable("MY_FLAG");
bool exists = RuntimeInformation.IsOSPlatform(OSPlatform.Linux)
    ? File.Exists($"/proc/self/environ") &&
      File.ReadAllText("/proc/self/environ")
          .Split('\0')
          .Any(e => e.StartsWith("MY_FLAG="))
    : val != null;

if (!exists)
{
    Console.WriteLine("MY_FLAG not set, using default");
}

